// Compares the shop's refund books with PayPal's records and books any refund the webhook missed.
async function reconcileOnce(db: Db, port: PaypalPort): Promise<void> {
  const orders = all(db, 'SELECT DISTINCT paypal_order_id FROM captures')
  for (const row of orders) {
    const orderId = String(row.paypal_order_id)
    try {
      const truth = await port.getOrder(orderId)
      for (const refund of truth.refunds) {
        run(db, 'INSERT OR IGNORE INTO refunds (paypal_refund_id, paypal_order_id, amount) VALUES (?, ?, ?)', refund.id, orderId, refund.amount)
      }
    } catch {
      // try again on the next tick
    }
  }
}

export function startReconcile(db: Db, port: PaypalPort): void {
  const timer = setInterval(() => {
    void reconcileOnce(db, port)
  }, 2000)
  timer.unref()
}
